using System.IO;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace NexoLauncher.App.UI;

internal static class NexaBrandAssets
{
    private const string WordmarkJpegBase64 = "";

    private const string FullJpegBase64 = "";

    public static ImageSource CreateWordmark() => Create(WordmarkJpegBase64);
    public static ImageSource CreateFull() => Create(FullJpegBase64);

    private static ImageSource Create(string base64)
    {
        var bytes = Convert.FromBase64String(base64);
        using var stream = new MemoryStream(bytes, writable: false);
        var image = new BitmapImage();
        image.BeginInit();
        image.CacheOption = BitmapCacheOption.OnLoad;
        image.CreateOptions = BitmapCreateOptions.PreservePixelFormat;
        image.StreamSource = stream;
        image.EndInit();
        image.Freeze();
        return image;
    }
}
